// Faithfully append fake-provider op-log lines, following the fake scripted-response
// protocol (resolve fixture paths -> load scripts -> compute seq/call-index -> resolve
// response -> append). Byte-exact responses are pulled straight from scripts.json so
// nothing is fabricated. Usage: node append-oplog.js '<json-array-of-ops>'
// each op = { surface, op, args, respFrom: {path:[...]} | {literal:<value>} }
const fs = require('fs');
const root = process.argv[2];
const opsSpec = JSON.parse(process.argv[3]);
const cfgScripts = root + '/_local/fake/scripts.json';
const oplog = root + '/_local/fake/op-log.jsonl';
const scripts = JSON.parse(fs.readFileSync(cfgScripts, 'utf8'));

function resolve(spec) {
  if ('literal' in spec) return spec.literal;
  let cur = scripts;
  for (const k of spec.path) cur = cur[k];
  return cur;
}

let existing = '';
try { existing = fs.readFileSync(oplog, 'utf8'); } catch (e) {}
let lines = existing.length ? existing.split('\n').filter(Boolean) : [];
for (const o of opsSpec) {
  const seq = lines.length + 1;
  const rec = { seq, surface: o.surface, op: o.op, args: o.args, response: resolve(o.respFrom) };
  lines.push(JSON.stringify(rec));
}
fs.writeFileSync(oplog, lines.join('\n') + '\n');
process.stdout.write('op-log now has ' + lines.length + ' lines\n');

